/**
 * Image edits shared by the editor and every web runtime: crop, fit, focal point and the
 * pixel adjustments that the older colour-matrix pipeline (exposure, contrast, saturation,
 * temperature, tint, highlights, shadows, negative, blur) doesn't cover.
 *
 * `prepareImage` turns a loaded image into a canvas laid out at the image box's aspect,
 * with these edits baked in. Callers draw that canvas stretched into the box and then run
 * the older adjustments on top, so files without new edits render exactly as before
 * (prepareImage returns null for them).
 *
 * Source of truth: packages/react/src/imageEdits.ts.
 * After editing run `node scripts/sync-image-edits.mjs` to copy it to the other runtimes.
 */
export type ImageFit = 'stretch' | 'fill' | 'fit' | 'tile';
/** Crop rectangle as fractions (0..1) of the source image. */
export interface ImageCrop {
    x: number;
    y: number;
    w: number;
    h: number;
}
export interface ImageLevels {
    inBlack?: number;
    inWhite?: number;
    gamma?: number;
    outBlack?: number;
    outWhite?: number;
}
export interface ImageDuotone {
    enabled?: boolean;
    shadow?: string;
    highlight?: string;
    amount?: number;
}
export interface ImageOverlay {
    enabled?: boolean;
    color?: string;
    amount?: number;
    blend?: 'normal' | 'multiply' | 'screen' | 'overlay' | 'color';
}
/** The fields of `geometry.adjustments` handled here (the rest belong to the older pipeline). */
export interface ImageEditAdjustments {
    hue?: number;
    vibrance?: number;
    whites?: number;
    blacks?: number;
    fade?: number;
    sepia?: number;
    clarity?: number;
    sharpen?: number;
    vignette?: number;
    vignetteSize?: number;
    posterize?: number;
    levels?: ImageLevels;
    /** Master tone curve: [x, y] points in 0..1, sorted by x. */
    curve?: number[][];
    duotone?: ImageDuotone;
    overlay?: ImageOverlay;
    gaussianBlur?: number;
    motionBlur?: number;
    motionAngle?: number;
    tiltShift?: number;
    tiltPosition?: number;
    tiltSize?: number;
}
export interface ImageEditGeometry {
    fit?: ImageFit;
    crop?: ImageCrop | null;
    focalX?: number;
    focalY?: number;
    tileSize?: number;
    adjustments?: ImageEditAdjustments & Record<string, any>;
}
/** True when a geometry uses anything this module draws (so the caller must use prepareImage). */
export declare function hasImageEdits(geometry?: ImageEditGeometry | null): boolean;
export declare function hasPixelEdits(a?: ImageEditAdjustments | null): boolean;
